function icon(string $name, string $class = 'size-[18px]'): string
{
    $paths = (array) (ICON_PATHS[$name] ?? []);
    $out = '<svg class="' . htmlspecialchars($class, ENT_QUOTES) . '" fill="none" stroke="currentColor" stroke-width="1.75" viewBox="0 0 24 24" aria-hidden="true">';
    foreach ($paths as $d) {
        $out .= '<path stroke-linecap="round" stroke-linejoin="round" d="' . $d . '"/>';
    }
    return $out . '</svg>';
}
